const tabId = 1962625065;
const searchDom = await browserjs(tabId, () => {
  const input = document.querySelector('input[placeholder*="Search"]');
  const btn = input ? input.parentElement.querySelector('button') : null;
  const rect = btn ? btn.getBoundingClientRect() : null;
  const elAtPoint = rect ? document.elementFromPoint(rect.x + rect.width/2, rect.y + rect.height/2) : null;
  return {
    inputVal: input?.value,
    btnTag: btn?.tagName,
    btnText: btn?.textContent,
    btnHtml: btn?.outerHTML,
    rect: rect ? { x: rect.x, y: rect.y, w: rect.width, h: rect.height } : null,
    elAtPoint: elAtPoint ? elAtPoint.outerHTML : null
  };
});
console.log(JSON.stringify(searchDom, null, 2));

