const tabId = 1962625065;
const categories = await browserjs(tabId, async () => {
  const headers = Array.from(document.querySelectorAll('button[data-testid="accordion-header"]'));
  for (const h of headers) {
    if (h.getAttribute('aria-expanded') === 'false') {
      h.click();
    }
  }
  await new Promise(r => setTimeout(r, 500));

  const results = [];
  const containers = Array.from(document.querySelectorAll('div[data-testid="accordion-container"]'));
  for (const c of containers) {
    const title = c.querySelector('[data-testid="accordion-title"]')?.textContent.trim();
    const items = Array.from(c.querySelectorAll('label')).map(l => l.textContent.trim().replace(/\s+/g, ' '));
    results.push({ title, items });
  }
  return results;
});
console.log(JSON.stringify(categories, null, 2));

