const filterDetails = await browserjs(tabId, () => {
  // Let's find the Support Services checkbox
  const labels = Array.from(document.querySelectorAll('label'));
  const ssLabel = labels.find(l => l.textContent.trim().toLowerCase() === 'support services');
  const ssInput = ssLabel ? (ssLabel.querySelector('input') || document.getElementById(ssLabel.getAttribute('for'))) : null;

  // Let's check all buttons inside the filter panel
  const filterPanel = ssLabel ? ssLabel.closest('div[role="dialog"]') || ssLabel.closest('div[class*="filter"]') || ssLabel.parentElement.parentElement.parentElement : null;

  const buttons = Array.from(document.querySelectorAll('button')).map(b => ({
    text: b.textContent.trim(),
    aria: b.getAttribute('aria-label'),
    testId: b.getAttribute('data-testid')
  })).filter(b => b.text || b.aria);

  return {
    ssLabelFound: !!ssLabel,
    ssInputFound: !!ssInput,
    ssInputChecked: ssInput?.checked,
    ssInputId: ssInput?.id,
    buttons: buttons.filter(b => b.text.toLowerCase().includes('apply') || b.text.toLowerCase().includes('filter') || b.text.toLowerCase().includes('result') || b.text.toLowerCase().includes('location'))
  };
});
console.log(JSON.stringify(filterDetails, null, 2));

