  const jobElements = Array.from(document.querySelectorAll('a')).filter(a => {
    return a.querySelector('button') || a.textContent.includes('Select') || a.href.includes('/role/') || a.href.includes('/job/');
  });

  const jobs = jobElements.map((el, index) => {
    // Extract title, location, pay, shifts, distance, etc.
    const text = el.textContent.trim().replace(/\s+/g, ' ');
    const title = el.querySelector('h2, h3, h4, [class*="title"]')?.textContent?.trim() || 'N/A';
    const href = el.href;
    return {
      index: index + 1,
      fullText: text,
      title,
      href
    };
  });

  // Check pagination
  const pagination = Array.from(document.querySelectorAll('[aria-label*="page"], [class*="pagination"] button, [data-testid*="pagination"]')).map(p => ({
    text: p.textContent.trim(),
    aria: p.getAttribute('aria-label')
  }));

  return {
    totalH1: document.querySelector('h1')?.textContent.trim(),
    jobsFoundCount: jobs.length,
    jobs,
    pagination
  };
});
console.log(JSON.stringify(jobsData, null, 2));

