const getPageJobs = async () => {
  return await browserjs(tabId, () => {
    const cards = Array.from(document.querySelectorAll('[data-id="job-card"], [data-testid="job-card"]'));
    return cards.map(c => {
      const jobId = c.getAttribute('data-job-id');
      const brandImg = c.querySelector('img');
      const brand = brandImg ? brandImg.getAttribute('alt') : '';

      // Let's get child text blocks
      // In the card, usually there are divs for title, facility, location, distance/pay
      const text = c.textContent.trim();
      const allDivs = Array.from(c.querySelectorAll('div')).map(d => d.textContent.trim()).filter(Boolean);

      return {
        jobId,
        brand,
        fullText: text,
        rawHtml: c.innerHTML
      };
    });
  });
};

const page1Jobs = await getPageJobs();
console.log(`Extracted ${page1Jobs.length} jobs from page 1`);

