const tabId = 1962625065;

// Function to extract structured data from job cards
const extractCards = () => {
  const cards = Array.from(document.querySelectorAll('[data-id="job-card"], [data-testid="job-card"]'));
  return cards.map(c => {
    const jobId = c.getAttribute('data-job-id');
    const brand = c.querySelector('img')?.getAttribute('alt') || 'Walmart';

    // The card has several text parts. Let's inspect its inner structure
    // Typically:
    // First child / elements: brand logo
    // Title: text before location
    // Location: Bentonville, AR
    // Pay: $...
    // Shifts: ...
    const fullText = c.textContent.trim().replace(/Select$/, '').trim();

    return {
      jobId,
      brand,
      cardText: fullText
    };
  });
};

