const tabId = 1962625065;

const parseCard = (card) => {
  const jobId = card.getAttribute('data-job-id');
  const brandAlt = card.querySelector('img')?.getAttribute('alt') || 'Walmart';
  const brand = brandAlt.replace(/logo/i, '').trim();
  const title = card.querySelector('[data-id="job-title"], [data-testid="job-title"]')?.textContent.trim();

  // Find all text elements in the card info container
  const spans = Array.from(card.querySelectorAll('span.text-\\[16px\\], span[class*="text-"]')).map(s => s.textContent.trim()).filter(Boolean);

  // Let's also look at all child divs
  const infoDiv = card.querySelector('div.flex.flex-col.gap-2');
  const details = infoDiv ? Array.from(infoDiv.children).map(c => c.textContent.trim().replace(/\s+/g, ' ')).filter(Boolean) : [];

  return {
    jobId,
    title,
    brand,
    details,
    spans
  };
};

// Extract Page 1
const page1Jobs = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('[data-id="job-card"], [data-testid="job-card"]'));
  return cards.map(c => {
    const jobId = c.getAttribute('data-job-id');
    const brandAlt = c.querySelector('img')?.getAttribute('alt') || 'Walmart';
    const brand = brandAlt.replace(/logo/i, '').trim();
    const title = c.querySelector('[data-id="job-title"], [data-testid="job-title"]')?.textContent.trim();
    const infoDiv = c.querySelector('div.flex.flex-col.gap-2');
    const details = infoDiv ? Array.from(infoDiv.querySelectorAll('span')).map(s => s.textContent.trim()).filter(Boolean) : [];
    return {
      jobId,
      title,
      brand,
      details
    };
  });
});

console.log(`Page 1 jobs parsed: ${page1Jobs.length}`);

// Click Page 2
await browserjs(tabId, () => {
  const p2 = Array.from(document.querySelectorAll('button')).find(b => b.getAttribute('aria-label') === 'Show me page number 2' || b.textContent.trim() === '2');
  if (p2) p2.click();
});

// Wait for load spinner to go away and page 2 to settle
await tool.wait_for({ tabId, condition: "selector_gone", value: 'img[alt="Loading…"]', timeout_ms: 10000 });
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

// Extract Page 2
const page2Jobs = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('[data-id="job-card"], [data-testid="job-card"]'));
  return cards.map(c => {
    const jobId = c.getAttribute('data-job-id');
    const brandAlt = c.querySelector('img')?.getAttribute('alt') || 'Walmart';
    const brand = brandAlt.replace(/logo/i, '').trim();
    const title = c.querySelector('[data-id="job-title"], [data-testid="job-title"]')?.textContent.trim();
    const infoDiv = c.querySelector('div.flex.flex-col.gap-2');
    const details = infoDiv ? Array.from(infoDiv.querySelectorAll('span')).map(s => s.textContent.trim()).filter(Boolean) : [];
    return {
      jobId,
      title,
      brand,
      details
    };
  });
});

console.log(`Page 2 jobs parsed: ${page2Jobs.length}`);

const allJobs = [...page1Jobs, ...page2Jobs];
console.log(`Total jobs: ${allJobs.length}`);
console.log(JSON.stringify(allJobs, null, 2));

// Save to scratch
await write("tmp://support_services_jobs_bentonville.json", JSON.stringify(allJobs, null, 2));

